 "content": "from collections import Counter


def _mode(values):
    return Counter(values).most_common(1)[0][0]


def _tracks(lines, background):
    """Track lines have a dominant rail color distinct from tile background."""
    coords = []
    colors = []
    for i, line in enumerate(lines):
        color, count = Counter(line).most_common(1)[0]
        if color != background and count > len(line) / 2:
            coords.append(i)
            colors.append(color)
    return coords, set(colors)


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the repeated tile background from overall cell frequency.
    background = _mode(v for row in grid for v in row)
    rows, row_colors = _tracks(grid, background)
    cols, col_colors = _tracks([list(col) for col in zip(*grid)], background)
    if len(rows) < 2 or len(cols) < 2:
        return [row[:] for row in grid]

    # Exclude separator lines to estimate the interior/background color robustly.
    interior = [grid[r][c] for r in range(h) for c in range(w)
                if r not in rows and c not in cols]
    if interior:
        background = _mode(interior)

    result = []
    for r0, r1 in zip(rows, rows[1:]):
        outrow = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            value = corners[0]
            if corners.count(value) == 4 and value not in row_colors | col_colors:
                outrow.append(value)
            else:
                outrow.append(background)
        result.append(outrow)

    # The outer lattice rails may be blank padding; remove only empty margins.
    occupied = [(r, c) for r, row in enumerate(result) for c, value in enumerate(row)
                if value != background]
    if occupied:
        r0 = min(r for r, _ in occupied)
        r1 = max(r for r, _ in occupied)
        c0 = min(c for _, c in occupied)
        c1 = max(c for _, c in occupied)
        result = [row[c0:c1 + 1] for row in result[r0:r1 + 1]]
    return result


def _check_demos():
    # Demo 1: period-5 horizontal and period-3 vertical scaffold.
    d1 = [[9 if c % 3 == 2 else 8 for c in range(23)] for _ in range(24)]
    d1[1] = [9] * 23
    d1[21] = [9] * 23
    for r, vals in ((6, {2: 3, 5: 3, 8: 2, 11: 2}),
                    (11, {2: 3, 5: 3, 8: 2, 11: 2, 14: 2, 17: 5, 20: 5}),
                    (16, {2: 3, 5: 3, 11: 2, 14: 2, 17: 5, 20: 5})):
        d1[r] = [9 if c % 3 == 2 else 8 for c in range(23)]
        for c, v in vals.items():
            d1[r][c] = v
    assert transform(d1) == [[3, 8, 2, 8, 8, 8], [3, 8, 8, 2, 8, 5]]

    # Demo 2: 6x8 cell spacing, with the final horizontal/vertical rails at edge.
    d2 = [[7] * 29 for _ in range(30)]
    for r in range(30):
        for c in (4, 12, 20, 28):
            d2[r][c] = 6
    for r in (4, 10, 16, 22, 28):
        d2[r] = [6] * 29
    for r in (4, 10):
        for c in (4, 12, 20):
            d2[r][c] = 4
    for r in (22, 28):
        for c, v in {4: 8, 12: 8, 20: 2, 28: 2}.items():
            d2[r][c] = v
    assert transform(d2) == [[4, 4, 7], [7, 7, 7], [7, 7, 7], [8, 7, 2]]

    # Demo 3: two vertical rails and three horizontal rails; unanimous corners encode 9.
    d3 = [[2] * 27 for _ in range(28)]
    for r in range(28):
        d3[r][6] = d3[r][25] = 1
    for r in (1, 13, 25):
        d3[r] = [1] * 27
        d3[r][6] = d3[r][25] = 9
    assert transform(d3) == [[9], [9]]


if __name__ == '__main__':
    _check_demos()
    test = [[4] * 27 for _ in range(29)]
    for r in list(range(1, 14)) + list(range(15, 28)):
        test[r] = [8 if c not in (1, 6, 11, 16, 21, 26) else 4 for c in range(27)]
    for c in (21, 26):
        test[0][c] = 3
    for c in (1, 6, 21, 26):
        test[14][c] = 3
    for c in (1, 6):
        test[28][c] = 3
    print(transform(test))
    print('all demo checks passed')
